SELECT * FROM (SELECT e.event_id,'Q:'||s.request_id case_id,e.activity,e.timestamp FROM (SELECT 'R:'||receipt_id event_id,'Receipt Registered' activity,received_at timestamp,receipt_id source_key FROM goods_receipt WHERE received_at IS NOT NULL AND (1=1)) e JOIN goods_receipt s ON s.receipt_id=e.source_key WHERE s.request_id IS NOT NULL UNION ALL SELECT e.event_id,'Q:'||r.request_id case_id,e.activity,e.timestamp FROM (SELECT 'M:'||movement_id event_id,'Goods Received' activity,occurred_at timestamp,movement_id source_key FROM goods_movement WHERE occurred_at IS NOT NULL AND (movement_code='IN')) e JOIN goods_movement s ON s.movement_id=e.source_key JOIN goods_receipt r ON r.receipt_id=s.receipt_id WHERE r.request_id IS NOT NULL UNION ALL SELECT e.event_id,'Q:'||s.request_id case_id,e.activity,e.timestamp FROM (SELECT 'T:'||task_id||':start' event_id,'Putaway Started' activity,started_at timestamp,task_id source_key FROM warehouse_task_history WHERE started_at IS NOT NULL AND (task_code='PUTAWAY')) e JOIN warehouse_task_history s ON s.task_id=e.source_key WHERE s.request_id IS NOT NULL UNION ALL SELECT e.event_id,'Q:'||s.request_id case_id,e.activity,e.timestamp FROM (SELECT 'T:'||task_id||':complete' event_id,'Putaway Completed' activity,completed_at timestamp,task_id source_key FROM warehouse_task_history WHERE completed_at IS NOT NULL AND (task_code='PUTAWAY')) e JOIN warehouse_task_history s ON s.task_id=e.source_key WHERE s.request_id IS NOT NULL UNION ALL SELECT e.event_id,'Q:'||s.request_id case_id,e.activity,e.timestamp FROM (SELECT 'H:'||handling_id||':start' event_id,'Unloading Started' activity,started_at timestamp,handling_id source_key FROM handling_history WHERE started_at IS NOT NULL AND (handling_code='UNLOAD')) e JOIN handling_history s ON s.handling_id=e.source_key WHERE s.request_id IS NOT NULL UNION ALL SELECT e.event_id,'Q:'||s.request_id case_id,e.activity,e.timestamp FROM (SELECT 'H:'||handling_id||':complete' event_id,'Unloading Completed' activity,completed_at timestamp,handling_id source_key FROM handling_history WHERE completed_at IS NOT NULL AND (handling_code='UNLOAD')) e JOIN handling_history s ON s.handling_id=e.source_key WHERE s.request_id IS NOT NULL) ORDER BY case_id,timestamp,event_id;
